/* G77, frozen protocol 85f58010. Diagnostic child, never a target controller.
 * Identity/memory idiom: evals/heavy_gate_native.c:46-54,76-83.
 * Fixed storage; no heap allocation, target signals, attachment, or fallback.
 */
#define _DARWIN_C_SOURCE
#include <sys/types.h>
#include <unistd.h>

#ifndef __APPLE__
int main(void) {
  static const char failure[] =
    "{\"schemaVersion\":1,\"status\":\"UNSUPPORTED_PLATFORM\","
    "\"targetPid\":null,\"targetStartMicros\":null,\"intervalMs\":null,"
    "\"capacity\":null,\"count\":0,\"columns\":[\"epochMs\",\"monotonicMs\","
    "\"rssBytes\",\"footprintBytes\",\"lifetimeHighFootprintBytes\"],"
    "\"samples\":[],\"stopReason\":\"startup_error\",\"overflow\":false,"
    "\"readErrors\":0,\"maxSampleGapMs\":0,\"self\":{\"userCpuMs\":null,"
    "\"systemCpuMs\":null,\"rssBytes\":null,\"footprintBytes\":null,"
    "\"lifetimeHighFootprintBytes\":null},\"scope\":\"Darwin required; no fallback\"}\n";
  (void)write(STDOUT_FILENO, failure, sizeof(failure) - 1);
  return 1;
}
#else
#include <sys/resource.h>
#include <libproc.h>
#include <stdint.h>
#include <inttypes.h>
#include <limits.h>
#include <signal.h>
#include <poll.h>
#include <fcntl.h>
#include <errno.h>
#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 4096U
#define NS_PER_MS UINT64_C(1000000)
#define CLOCK_TOLERANCE_NS (UINT64_C(10) * NS_PER_MS)
#define OUTPUT_TIMEOUT_NS (UINT64_C(5000) * NS_PER_MS)

typedef struct {
  uint64_t epoch, monotonic, rss, footprint, high;
} Sample;
static Sample samples[MAX_RECORDS];
static unsigned count, capacity, interval_ms, read_errors;
static pid_t target_pid;
static uint64_t target_start, previous_clock_span, max_gap;
static int bound, overflow;
static const char *status = "PASS";
static const char *stop_reason = "startup_error";
static volatile sig_atomic_t interrupted;
static char output_buffer[8192];
static size_t output_used;
static uint64_t output_deadline;
static int output_failed;

static void on_signal(int sig) {
  if (!interrupted) interrupted = sig;
}

static void fail(const char *reason) {
  if (strcmp(status, "PASS") == 0) status = reason;
}

static void signal_status(void) {
  if (interrupted) {
    fail(interrupted == SIGTERM ? "SIGNAL_SIGTERM" : "SIGNAL_SIGINT");
    stop_reason = interrupted == SIGTERM ? "SIGTERM" : "SIGINT";
  }
}

static int clock_ns(clockid_t clock, uint64_t *out) {
  struct timespec t;
  if (clock_gettime(clock, &t) != 0 || t.tv_sec < 0 ||
      (uint64_t)t.tv_sec > (UINT64_MAX - UINT64_C(999999999)) / UINT64_C(1000000000) ||
      t.tv_nsec < 0 || t.tv_nsec >= 1000000000L) return -1;
  *out = (uint64_t)t.tv_sec * UINT64_C(1000000000) + (uint64_t)t.tv_nsec;
  return 0;
}

static int decimal(const char *text, unsigned min, unsigned max, unsigned *out) {
  unsigned value = 0;
  if (!*text) return -1;
  for (; *text; ++text) {
    if (*text < '0' || *text > '9') return -1;
    unsigned digit = (unsigned)(*text - '0');
    if (value > (max - digit) / 10U) return -1;
    value = value * 10U + digit;
  }
  if (value < min || value > max) return -1;
  *out = value;
  return 0;
}

static int identity(uint64_t *start) {
  struct proc_bsdinfo b;
  if (getppid() != target_pid) {
    fail("TARGET_NOT_DIRECT_PARENT");
    return -1;
  }
  if (proc_pidinfo(target_pid, PROC_PIDTBSDINFO, 0, &b, sizeof(b)) != (int)sizeof(b)) {
    ++read_errors;
    fail("TARGET_IDENTITY_READ_ERROR");
    return -1;
  }
  if (b.pbi_pid != (uint32_t)target_pid || b.pbi_status == 5) {
    fail("TARGET_IDENTITY_INVALID");
    return -1;
  }
  *start = (uint64_t)b.pbi_start_tvsec * UINT64_C(1000000) + b.pbi_start_tvusec;
  if (bound && *start != target_start) {
    fail("TARGET_IDENTITY_CHANGED");
    return -1;
  }
  return 0;
}

/* Timestamps precede the memory read, bracketed by identity reads. They do not
 * imply an atomic clock/memory snapshot or isolate-level ownership. */
static int take_sample(void) {
  uint64_t start, before, after, epoch;
  struct rusage_info_v4 r;
  if (count >= capacity) {
    overflow = 1;
    fail("CAPACITY_EXCEEDED");
    return -1;
  }
  if (identity(&start) != 0) return -1;
  if (clock_ns(CLOCK_MONOTONIC, &before) != 0 ||
      clock_ns(CLOCK_REALTIME, &epoch) != 0 ||
      clock_ns(CLOCK_MONOTONIC, &after) != 0) {
    ++read_errors;
    fail("CLOCK_READ_ERROR");
    return -1;
  }
  if (after < before) {
    fail("CLOCK_DISCONTINUITY");
    return -1;
  }
  if (proc_pid_rusage(target_pid, RUSAGE_INFO_V4, (rusage_info_t *)&r) != 0) {
    ++read_errors;
    fail("TARGET_MEMORY_READ_ERROR");
    return -1;
  }
  if (identity(&start) != 0) return -1;
  Sample *row = &samples[count];
  row->epoch = epoch;
  row->monotonic = before + (after - before) / 2;
  row->rss = r.ri_resident_size;
  row->footprint = r.ri_phys_footprint;
  row->high = r.ri_lifetime_max_phys_footprint;
  int clock_issue = 0;
  if (count) {
    const Sample *previous = &samples[count - 1];
    if (row->monotonic >= previous->monotonic) {
      uint64_t gap = row->monotonic - previous->monotonic;
      if (gap > max_gap) max_gap = gap;
    }
    if (row->monotonic < previous->monotonic || row->epoch < previous->epoch) {
      clock_issue = 1;
    } else {
      uint64_t gap = row->monotonic - previous->monotonic;
      uint64_t epoch_gap = row->epoch - previous->epoch;
      uint64_t difference = gap > epoch_gap ? gap - epoch_gap : epoch_gap - gap;
      if (difference > CLOCK_TOLERANCE_NS + previous_clock_span + after - before)
        clock_issue = 1;
    }
  }
  previous_clock_span = after - before;
  ++count;
  if (clock_issue) {
    fail("CLOCK_DISCONTINUITY");
    return -1;
  }
  return 0;
}

/* Nonblocking stdout and a deadline per whole JSON line avoid hanging on a
 * parent that stops draining. A broken/partial stream is never success. */
static int output_begin(void) {
  uint64_t now;
  output_used = 0;
  if (clock_ns(CLOCK_MONOTONIC, &now) != 0) return -1;
  output_deadline = now + OUTPUT_TIMEOUT_NS;
  return 0;
}

static int output_flush(void) {
  size_t offset = 0;
  while (offset < output_used) {
    uint64_t now;
    if (clock_ns(CLOCK_MONOTONIC, &now) != 0 || now >= output_deadline) {
      output_failed = 1;
      return -1;
    }
    ssize_t n = write(STDOUT_FILENO, output_buffer + offset, output_used - offset);
    if (n > 0) {
      offset += (size_t)n;
      continue;
    }
    if (n < 0 && errno == EINTR) continue;
    if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
      struct pollfd fd = {STDOUT_FILENO, POLLOUT, 0};
      int rc = poll(&fd, 1, 100);
      if (rc >= 0 && !(fd.revents & (POLLERR | POLLHUP | POLLNVAL))) continue;
      if (rc < 0 && errno == EINTR) continue;
    }
    output_failed = 1;
    return -1;
  }
  output_used = 0;
  return 0;
}

static void emit(const char *format, ...) {
  if (output_failed) return;
  if (sizeof(output_buffer) - output_used < 1024 && output_flush() != 0) return;
  va_list args;
  va_start(args, format);
  int n = vsnprintf(output_buffer + output_used, sizeof(output_buffer) - output_used,
                    format, args);
  va_end(args);
  if (n < 0 || (size_t)n >= sizeof(output_buffer) - output_used) {
    output_failed = 1;
    return;
  }
  output_used += (size_t)n;
}

static void emit_identity(void) {
  emit("\"targetPid\":");
  if (target_pid) emit("%d", (int)target_pid);
  else emit("null");
  emit(",\"targetStartMicros\":");
  if (bound) emit("%" PRIu64, target_start);
  else emit("null");
  emit(",\"intervalMs\":%u,\"capacity\":%u", interval_ms, capacity);
}

static int emit_final(void) {
  struct rusage cpu;
  struct rusage_info_v4 memory;
  int cpu_ok = getrusage(RUSAGE_SELF, &cpu) == 0;
  int memory_ok = proc_pid_rusage(getpid(), RUSAGE_INFO_V4, (rusage_info_t *)&memory) == 0;
  if (!cpu_ok) { ++read_errors; fail("SELF_CPU_READ_ERROR"); }
  if (!memory_ok) { ++read_errors; fail("SELF_MEMORY_READ_ERROR"); }
  if (output_begin() != 0) return -1;
  emit("{\"schemaVersion\":1,");
  emit_identity();
  emit(",\"count\":%u,\"columns\":[\"epochMs\",\"monotonicMs\",\"rssBytes\","
       "\"footprintBytes\",\"lifetimeHighFootprintBytes\"],\"samples\":[", count);
  for (unsigned i = 0; i < count && !output_failed; ++i) {
    const Sample *r = &samples[i];
    emit("%s[%" PRIu64 ".%03" PRIu64 ",%" PRIu64 ".%03" PRIu64
         ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 "]",
         i ? "," : "", r->epoch / NS_PER_MS, r->epoch % NS_PER_MS / 1000,
         r->monotonic / NS_PER_MS, r->monotonic % NS_PER_MS / 1000,
         r->rss, r->footprint, r->high);
  }
  emit("],\"overflow\":%s,\"readErrors\":%u,\"maxSampleGapMs\":%" PRIu64
       ".%03" PRIu64 ",\"self\":{",
       overflow ? "true" : "false", read_errors, max_gap / NS_PER_MS,
       max_gap % NS_PER_MS / 1000);
  if (cpu_ok) {
    int64_t user_us = (int64_t)cpu.ru_utime.tv_sec * INT64_C(1000000) + cpu.ru_utime.tv_usec;
    int64_t system_us = (int64_t)cpu.ru_stime.tv_sec * INT64_C(1000000) + cpu.ru_stime.tv_usec;
    emit("\"userCpuMs\":%" PRId64 ".%03" PRId64 ",\"systemCpuMs\":%" PRId64 ".%03" PRId64 ",",
         user_us / 1000, user_us % 1000, system_us / 1000, system_us % 1000);
  } else emit("\"userCpuMs\":null,\"systemCpuMs\":null,");
  if (memory_ok) {
    emit("\"rssBytes\":%" PRIu64 ",\"footprintBytes\":%" PRIu64
         ",\"lifetimeHighFootprintBytes\":%" PRIu64,
         memory.ri_resident_size, memory.ri_phys_footprint, memory.ri_lifetime_max_phys_footprint);
  } else emit("\"rssBytes\":null,\"footprintBytes\":null,\"lifetimeHighFootprintBytes\":null");
  signal_status();
  emit("},\"scope\":\"Direct-parent process only, not worker isolate or whole tree; "
       "CLOCK_REALTIME epochMs and CLOCK_MONOTONIC monotonicMs precede libproc memory read; "
       "lifetime high predates observation; self measured before final serialization\","
       "\"stopReason\":\"%s\",\"status\":\"%s\"}\n", stop_reason, status);
  if (output_flush() != 0 || output_failed) return -1;
  return 0;
}

static int make_nonblocking(int fd) {
  int flags = fcntl(fd, F_GETFL);
  return flags < 0 ? -1 : fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

int main(int argc, char **argv) {
  unsigned pid = 0;
  struct sigaction action;
  memset(&action, 0, sizeof(action));
  action.sa_handler = on_signal;
  sigemptyset(&action.sa_mask);
  if (sigaction(SIGTERM, &action, NULL) != 0 || sigaction(SIGINT, &action, NULL) != 0)
    fail("SIGNAL_SETUP_ERROR");
  action.sa_handler = SIG_IGN;
  if (sigaction(SIGPIPE, &action, NULL) != 0) fail("SIGNAL_SETUP_ERROR");
  if (make_nonblocking(STDOUT_FILENO) != 0) return 2;
  if (argc != 7 || strcmp(argv[1], "--pid") || strcmp(argv[3], "--interval-ms") ||
      strcmp(argv[5], "--max-records") || decimal(argv[2], 2, INT_MAX, &pid) ||
      decimal(argv[4], 1, 60000, &interval_ms) || decimal(argv[6], 2, MAX_RECORDS, &capacity)) {
    fail("INVALID_ARGUMENTS");
  } else target_pid = (pid_t)pid;
  if (strcmp(status, "PASS") == 0 && make_nonblocking(STDIN_FILENO) != 0)
    fail("STDIN_SETUP_ERROR");
  if (strcmp(status, "PASS") == 0 && identity(&target_start) == 0) bound = 1;
  int can_final_sample = 0;
  if (bound && take_sample() == 0) can_final_sample = 1;
  signal_status();
  if (strcmp(status, "PASS") == 0) {
    if (output_begin() != 0) return 2;
    emit("{\"schemaVersion\":1,\"status\":\"READY\",");
    emit_identity();
    emit("}\n");
    if (output_flush() != 0 || output_failed) return 2;
    uint64_t due = samples[count - 1].monotonic + (uint64_t)interval_ms * NS_PER_MS;
    char command[5];
    size_t command_used = 0;
    stop_reason = "sampling_error";
    for (;;) {
      if (interrupted) { signal_status(); break; }
      if (getppid() != target_pid) { fail("TARGET_NOT_DIRECT_PARENT"); can_final_sample = 0; break; }
      uint64_t now;
      if (clock_ns(CLOCK_MONOTONIC, &now) != 0) {
        ++read_errors; fail("CLOCK_READ_ERROR"); can_final_sample = 0; break;
      }
      int wait_ms = now >= due ? 0 : (int)((due - now + NS_PER_MS - 1) / NS_PER_MS);
      if (wait_ms > 100) wait_ms = 100;
      struct pollfd fd = {STDIN_FILENO, POLLIN, 0};
      int rc = poll(&fd, 1, wait_ms);
      if (rc < 0) {
        if (errno == EINTR) continue;
        fail("STDIN_POLL_ERROR"); break;
      }
      if (interrupted) { signal_status(); break; }
      if (fd.revents & POLLNVAL) { fail("STDIN_POLL_ERROR"); break; }
      if (fd.revents & (POLLIN | POLLHUP | POLLERR)) {
        char input[64];
        ssize_t n = read(STDIN_FILENO, input, sizeof(input));
        if (n == 0) {
          if (command_used && !(command_used == 4 && memcmp(command, "STOP", 4) == 0))
            fail("INVALID_STOP_COMMAND");
          stop_reason = "EOF";
          break;
        }
        if (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR) {
          ++read_errors; fail("STDIN_READ_ERROR"); break;
        }
        int stop = 0;
        for (ssize_t i = 0; i < n; ++i) {
          if (input[i] == '\n') {
            if ((command_used == 4 || (command_used == 5 && command[4] == '\r')) &&
                memcmp(command, "STOP", 4) == 0 && i == n - 1) {
              stop_reason = "STOP";
            } else fail("INVALID_STOP_COMMAND");
            stop = 1;
            break;
          }
          if (command_used == sizeof(command)) { fail("INVALID_STOP_COMMAND"); stop = 1; break; }
          command[command_used++] = input[i];
          if ((command_used <= 4 && input[i] != "STOP"[command_used - 1]) ||
              (command_used == 5 && input[i] != '\r')) {
            fail("INVALID_STOP_COMMAND"); stop = 1; break;
          }
        }
        if (stop) break;
        if (fd.revents & POLLERR) { fail("STDIN_POLL_ERROR"); break; }
      }
      if (clock_ns(CLOCK_MONOTONIC, &now) != 0) {
        ++read_errors; fail("CLOCK_READ_ERROR"); can_final_sample = 0; break;
      }
      if (now >= due) {
        /* Reserve one row for the final sample, even on overflow. */
        if (count >= capacity - 1) {
          overflow = 1; fail("CAPACITY_EXCEEDED"); stop_reason = "capacity"; break;
        }
        if (take_sample() != 0) { can_final_sample = 0; break; }
        /* No synthetic catch-up rows after scheduling delays. */
        due = samples[count - 1].monotonic + (uint64_t)interval_ms * NS_PER_MS;
      }
    }
  }
  if (can_final_sample) (void)take_sample();
  signal_status();
  if (emit_final() != 0) return 2;
  return interrupted || strcmp(status, "PASS") != 0 ? 1 : 0;
}
#endif
